private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty graph is trivially a clique
    }

    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex.equals(otherVertex)) {
                continue; // Skip self-comparison
            }
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false; // If any edge is missing, it's not a clique
            }
        }
    }
    return true; // All edges present, it's a clique
}

